fields.default:
.report-table { width:100%; border-collapse:collapse; font-size:13px; margin:10px 0 25px 0; }
.report-table th { background:#f1f3f4; padding:8px; text-align:left; border-bottom:2px solid #ccc; font-weight:600; }
.report-table td { padding:8px; border-bottom:1px solid #eee; vertical-align:top; }
.callout-warn { background:#fff8e1; border-left:4px solid #ffa000; padding:12px 15px; margin:20px 0; border-radius:4px; }
.cta { display:inline-block; background:#1a73e8; color:white; padding:10px 25px; border-radius:6px; text-decoration:none; font-weight:600; }
